"""Version-locked live access to the game. Generated by the game-trainer skill."""
import hashlib, json, os, struct
from pathlib import Path
from processes import mapped_pids

ROOT = Path(__file__).resolve().parent
CONFIG = json.loads((ROOT / 'config.json').read_text())


class Game:
    def __init__(self, executable=None):
        self.exe = Path(executable or CONFIG['executable']).resolve()
        if hashlib.sha256(self.exe.read_bytes()).hexdigest() != CONFIG['sha256']:
            raise RuntimeError('Unsupported game build. Re-validate before use.')
        pids = mapped_pids(self.exe)
        if len(pids) != 1:
            raise RuntimeError('Start exactly one copy of the game, then connect.')
        self.pid = pids[0]
        self.start = self.identity()
        self.fd = os.open(f'/proc/{self.pid}/mem', os.O_RDWR)

    def identity(self):
        # Field 22 of stat, the start time, tells a recycled pid from this game.
        return Path(f'/proc/{self.pid}/stat').read_text().rsplit(')', 1)[1].split()[19]

    def alive(self):
        try:
            return self.identity() == self.start
        except OSError:
            return False

    def close(self):
        if self.fd is not None:
            os.close(self.fd)
            self.fd = None

    def read(self, address, size):
        if not self.alive():
            raise RuntimeError('Game exited.')
        data = os.pread(self.fd, size, address)
        if len(data) != size:
            raise RuntimeError('Incomplete memory read.')
        return data

    def u32(self, address):
        return struct.unpack('<I', self.read(address, 4))[0]

    def write(self, address, expected, new):
        """Write only over known bytes, then read back. Never overwrite the unknown."""
        if len(expected) != len(new):
            raise ValueError('Replacement must match the original length.')
        if self.read(address, len(expected)) != expected:
            raise RuntimeError(f'Unexpected bytes at {address:#x}; refusing to write.')
        if os.pwrite(self.fd, new, address) != len(new) or self.read(address, len(new)) != new:
            raise RuntimeError(f'Write to {address:#x} did not stick.')

    def ready(self):
        """Replace with real checks: loaded save, single-player, player object valid.

        A live process is not a playable game. Effects stay off until this is true.
        """
        return False
